// @vitest-environment jsdom
// All base payloads are generated by the real native DesktopController. Inputs
// below are pointer/keyboard or failure-rendering assertions, never Tori rules.
import { afterEach, expect, it, vi } from "vitest";
import { cleanup, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { invoke } from "@tauri-apps/api/core";
import { GameBoard } from "./GameBoard";
import { ApplicationView } from "./ApplicationView";
import { NativeHistory } from "./NativeSessionPanels";
import { NativeBoard } from "../NativeBoard";
import type { ToriSnapshot, GameSnapshot } from "./native";
import type { GameSession } from "./useGameSession";
import type { MovementInspection } from "./movementInspection";
import contractJson from "../__fixtures__/shared-tori-contract.json";
import capturedJson from "../__fixtures__/shared-tori-captured-promoted.json";
import capacityDeadlineJson from "../__fixtures__/shared-tori-capacity-deadline.json";
import fileDeadlineJson from "../__fixtures__/shared-tori-file-deadline.json";
import goteJson from "../__fixtures__/shared-tori-gote.json";
import dropJson from "../__fixtures__/shared-tori-dropped.json";
import historyJson from "../__fixtures__/shared-tori-selected-root.json";
import resignedJson from "../__fixtures__/shared-tori-resigned.json";
import repetitionJson from "../__fixtures__/shared-tori-repetition.json";
import prefixJson from "../__fixtures__/shared-tori-repetition-prefix.json";
import pendingJson from "../__fixtures__/shared-tori-pending-unsupported.json";
import unsupportedJson from "../__fixtures__/shared-tori-unsupported.json";
import resourceJson from "../__fixtures__/shared-tori-resource.json";
import inspectionJson from "../__fixtures__/shared-tori-inspections.json";
import shogiJson from "../__fixtures__/shared-shogi-standard.json";
vi.mock("@tauri-apps/api/core", () => ({ invoke: vi.fn() }));
afterEach(() => { cleanup(); vi.resetAllMocks(); });
const root = contractJson as unknown as ToriSnapshot;
const inspections = inspectionJson as unknown as MovementInspection[];
function board(snapshot = root, command = vi.fn()) { return { ...render(<GameBoard snapshot={snapshot} disabled={false} inspectionDisabled={false} command={command} />), command }; }
function session(snapshot: GameSnapshot): GameSession { return { snapshot, busy: false, error: "", command: vi.fn(), file: vi.fn(), newGame: vi.fn(), closeRequested: false, cancelClose: vi.fn(), finishClose: vi.fn(), requestClose: vi.fn() }; }
function app(snapshot: ToriSnapshot) { const native = session(snapshot); return { ...render(<ApplicationView snapshot={snapshot} session={native} onNewGame={vi.fn()} onOpen={vi.fn()} blocked={false} />), native }; }
it("presents all nine native faces, handed resources, exact7x7 orientations and technical status", () => {
  board();
  for (const piece of root.pieces) expect(screen.getByRole("button", { name: piece.label })).toBeTruthy();
  expect(new Set(root.pieces.map(p => p.kind)).size).toBe(9);
  expect(root.pieces.some(p => p.kind === "Ea" && p.promoted)).toBe(true);
  expect(screen.getByRole("button", { name: "Sente Right Quail in hand, 1" })).toBeTruthy();
  expect(screen.getByRole("button", { name: "Gote Left Quail in hand, 1" })).toBeTruthy();
  expect(screen.getByRole("group", { name: /7×7.*Sente at bottom/ })).toBeTruthy();
  expect(screen.getByText(/Development contract verification/)).toBeTruthy();
  cleanup(); board(goteJson as unknown as ToriSnapshot);
  expect(screen.getByRole("group", { name: /7×7.*Gote at bottom/ })).toBeTruthy();
});
it("submits one complete forced promotion with capture, without an optional promotion dialog", async () => {
  const user = userEvent.setup(), { command } = board();
  await user.click(screen.getByRole("button", { name: "7c, Sente Falcon" }));
  await user.click(screen.getByRole("button", { name: /7b, Gote Swallow.*legal destination/ }));
  expect(command).toHaveBeenCalledExactlyOnceWith({ kind: "tori", actor: "sente", command: { kind: "play", action: { kind: "move", from: "7c", to: "7b", result_face: "eagle" } } });
  expect(screen.queryByRole("dialog")).toBeNull();
  await user.click(screen.getByRole("button", { name: /7b, Gote Swallow/ })); expect(command).toHaveBeenCalledTimes(1);
});
it("uses the native handed drop identity and restores keyboard focus on Escape", async () => {
  const user = userEvent.setup(), { command } = board();
  const hand = screen.getByRole("button", { name: "Sente Right Quail in hand, 1" }); hand.focus();
  await user.keyboard("{Enter}{Escape}"); expect(document.activeElement).toBe(hand); expect(command).not.toHaveBeenCalled();
  await user.click(hand); await user.click(screen.getByRole("button", { name: /5e, empty.*legal destination/ }));
  expect(command).toHaveBeenCalledExactlyOnceWith({ kind: "tori", actor: "sente", command: { kind: "play", action: { kind: "drop", face: "right_quail", to: "5e" } } });
});
it("keyboard board navigation cancels partial selection without applying anything", async () => {
  const user = userEvent.setup(), { command } = board();
  const phoenix = screen.getByRole("button", { name: "4g, Sente Phoenix" }); phoenix.focus();
  await user.keyboard("{Enter}{Escape}"); expect(document.activeElement).toBe(phoenix); expect(command).not.toHaveBeenCalled();
  await user.keyboard("{ArrowRight}"); expect(document.activeElement?.getAttribute("aria-label")).toBe("3g, empty");
});
it.each(["4a", "hand:mshogi.tori.modern.v1:gote:LQ"])("inspects native opponent origin%s with non-actionable markers and common status", async origin => {
  const native = inspections.find(i => i.origin === origin)!; vi.mocked(invoke).mockResolvedValue(native);
  const user = userEvent.setup(), { command } = board();
  const source = origin === "4a" ? screen.getByRole("button", { name: "4a, Gote Phoenix" }) : screen.getByRole("button", { name: "Gote Left Quail in hand, 1" });
  await user.click(source); await waitFor(() => expect(screen.getByText(`Inspecting ${native.label} · Esc clears`)).toBeTruthy());
  expect(document.querySelectorAll(".inspection-marker").length).toBeGreaterThan(0);
  const destination = native.choices[0]!.steps[0]!; const target = screen.getByRole("button", { name: new RegExp(`^${destination},.*read-only inspection destination`) });
  await user.click(target); expect(command).not.toHaveBeenCalled(); await user.keyboard("{Escape}"); expect(document.activeElement).toBe(source);
});
it("retires a delayed inspection across exact selection and game replacement", async () => {
  let resolve!: (value: unknown) => void; vi.mocked(invoke).mockImplementation(() => new Promise(r => { resolve = r; }));
  const user = userEvent.setup(), command = vi.fn(); const { rerender } = board(root, command);
  await user.click(screen.getByRole("button", { name: "4a, Gote Phoenix" }));
  rerender(<GameBoard snapshot={historyJson as unknown as ToriSnapshot} disabled={false} inspectionDisabled={false} command={command} />);
  resolve(inspections.find(i => i.origin === "4a")); await waitFor(() => expect(screen.queryByText(/^Inspecting /)).toBeNull()); expect(command).not.toHaveBeenCalled();
  rerender(<GameBoard snapshot={root} disabled={false} inspectionDisabled={false} command={command} />);
  await user.click(screen.getByRole("button", { name: "4a, Gote Phoenix" }));
  rerender(<GameBoard snapshot={shogiJson as unknown as GameSnapshot} disabled={false} inspectionDisabled={false} command={command} />);
  resolve(inspections.find(i => i.origin === "4a")); await waitFor(() => expect(screen.queryByText(/^Inspecting /)).toBeNull()); expect(command).not.toHaveBeenCalled();
});
it("cannot override native historical admission with disabled=false, while readonly inspection stays enabled", async () => {
  const native = historyJson as unknown as ToriSnapshot, onPlay = vi.fn();
  const onInspect = vi.fn().mockResolvedValue(null); render(<NativeBoard snapshot={native} bottomSide={native.sides[0]!.key} disabled={false} inspectionDisabled={false} onInspect={onInspect} onPlay={onPlay} />);
  await userEvent.click(screen.getByRole("button", { name: "4g, Sente Phoenix" })); expect(onPlay).not.toHaveBeenCalled(); expect(onInspect).toHaveBeenCalledWith("4g");
});
it("projects only board rows, native nonmove events and selected completed geometry", () => {
  const ended = resignedJson as unknown as ToriSnapshot; render(<NativeHistory snapshot={ended} disabled={false} command={vi.fn()} />);
  expect(ended.moves.entries).toHaveLength(1); expect(ended.events).toHaveLength(3);
  expect(screen.getByRole("button", { name: /1. Sente: Technical:/ })).toBeTruthy(); expect(screen.getByText(/Position events \(2\)/)).toBeTruthy();
  cleanup(); const { container, rerender } = board(dropJson as unknown as ToriSnapshot);
  expect(container.querySelector(".completed-action-origin")).toBeNull(); expect(container.querySelector(".completed-action-destination")).not.toBeNull();
  rerender(<GameBoard snapshot={historyJson as unknown as ToriSnapshot} disabled={false} inspectionDisabled={false} command={vi.fn()} />);
  expect(container.querySelector(".completed-action-cue")).toBeNull();
});
it("keeps repetition advice separate from a conclusion and never leaks live obligations into a prefix", () => {
  const native = repetitionJson as unknown as ToriSnapshot; app(native);
  expect(screen.getByText(/Repetition obligation:/)).toBeTruthy(); expect(screen.queryByLabelText("Game outcome")).toBeNull();
  cleanup(); app(prefixJson as unknown as ToriSnapshot); expect(screen.queryByText(/Repetition obligation:/)).toBeNull();
  expect(screen.getByRole("button", { name: "Return to live" })).toBeTruthy();
});
it.each([pendingJson, unsupportedJson])("cannot advertise a real unsupported native probe as play, analysis or telemetry", fixture => {
  app(fixture as unknown as ToriSnapshot);
  expect(screen.getByText("Engine unavailable")).toBeTruthy();
  for (const name of [/Resume play/, /Retry engine/, /Start move analysis/, /Cancel search/]) expect(screen.queryByRole("button", { name })).toBeNull();
  expect(screen.queryByText("mShogi is thinking")).toBeNull(); expect(screen.queryByText(/Completed depth/)).toBeNull();
});
it("renders actual native oversized-Open refusal, keeps Save available and does not claim an engine or game failure", () => {
  app(resourceJson as unknown as ToriSnapshot);
  expect(screen.getByRole("alert").textContent).toContain("byte capacity"); expect(screen.queryByLabelText("Game outcome")).toBeNull();
  expect((screen.getByRole("button", { name: "Save" }) as HTMLButtonElement).disabled).toBe(false);
});

it.each([capturedJson, pendingJson])("retains native origin and emphasized destination for capture, including unsupported pending work", fixture => {
  const { container } = board(fixture as unknown as ToriSnapshot);
  expect(container.querySelector('.completed-action-origin')).not.toBeNull();
  expect(container.querySelector('.completed-action-destination[data-cue-signature="double-underline"]')).not.toBeNull();
  expect((fixture as unknown as ToriSnapshot).moves.last_action?.origin).toEqual({ kind: "board", square: "7c" });
});
it.each([capacityDeadlineJson, fileDeadlineJson])("renders the real native elapsed-budget classifier without promising Save or reclassifying it as a chess result", fixture => {
  app(fixture as unknown as ToriSnapshot);
  expect(screen.getByRole("alert").textContent).toContain("time budget");
  expect(screen.getByRole("alert").textContent).toContain("kept");
  expect(screen.queryByLabelText("Game outcome")).toBeNull();
  expect(screen.queryByText(/Engine connection failed/)).toBeNull();
  expect(screen.queryByText(/Save to keep the complete current game, then start a new game/)).toBeNull();
  expect((screen.getByRole("button", { name: "Save" }) as HTMLButtonElement).disabled).toBe(false);
  for (const name of [/Resume play/, /Retry engine/]) expect(screen.queryByRole("button", { name })).toBeNull();
});
